begin; select no_plan();
insert into public.profiles(id) values('00000000-0000-4000-8000-000000001627'),('00000000-0000-4000-8000-000000001628'),('00000000-0000-4000-8000-000000001630');
select * from public.operational_access_set('00000000-0000-4000-8000-000000001627','owner','grant','test:admin','Admin r1','test:r1',null);
create temporary table creator_probe as select public.native_admin_execute('00000000-0000-4000-8000-000000001627','https://clerk.admin.test','create_creator','{"name":"Carlos GT","email":"carlos@example.invalid","code":"CARLOSGT"}','sandbox') result;
select public.native_admin_execute('00000000-0000-4000-8000-000000001627','https://clerk.admin.test','activate_creator',jsonb_build_object('creator_id',(select result->'creator'->>'creator_id' from creator_probe),'discount_id','discount-test'),'sandbox');
select lives_ok($$select public.native_admin_record_payment('sandbox','{"payment_id":"order-1","account_id":"00000000-0000-4000-8000-000000001628","subscription_id":"sub-1","product":"Pro mensual","paid_at":"2026-08-31T00:00:00Z","amount_cents":319,"currency":"eur","discount_id":"discount-test","modified_at":"2026-08-31T00:00:00Z","refunded_cents":0}')$$,'pago atribuido del servidor');
select lives_ok($$select public.native_admin_record_payment('sandbox','{"payment_id":"order-2","account_id":"00000000-0000-4000-8000-000000001628","subscription_id":"sub-1","product":"Pro mensual","paid_at":"2026-09-01T00:00:00Z","amount_cents":319,"currency":"eur","modified_at":"2026-09-01T00:00:00Z","refunded_cents":0}')$$,'renovación conserva primer código');
select public.native_admin_execute('00000000-0000-4000-8000-000000001627','https://clerk.admin.test','finish_payment_sync','{"account_ids":["00000000-0000-4000-8000-000000001628","00000000-0000-4000-8000-000000001630"]}','sandbox');
select is(public.native_admin_execute('00000000-0000-4000-8000-000000001627','https://clerk.admin.test','get_creator',jsonb_build_object('creator_id',(select result->'creator'->>'creator_id' from creator_probe)),'sandbox')->'creator'->>'earned_cents','192','un cobro adicional antes de cumplir el primer mes conserva el 30 por ciento');
select public.native_admin_record_payment('sandbox','{"payment_id":"annual-1","account_id":"00000000-0000-4000-8000-000000001630","subscription_id":"annual","product":"Pro anual","paid_at":"2025-09-01T00:00:00Z","amount_cents":6990,"currency":"eur","discount_id":"discount-test","modified_at":"2025-09-01T00:00:00Z","refunded_cents":0}');
select public.native_admin_record_payment('sandbox','{"payment_id":"annual-2","account_id":"00000000-0000-4000-8000-000000001630","subscription_id":"annual","product":"Pro anual","paid_at":"2026-09-01T00:00:00Z","amount_cents":6990,"currency":"eur","modified_at":"2026-09-01T00:00:00Z","refunded_cents":0}');
select is((select item->>'commission_cents' from private.native_admin_creator_lines('sandbox') where item->>'payment_id'='annual-1'),'2097','anual primer mes aplica 30 por ciento a lo cobrado');
select is((select item->>'commission_cents' from private.native_admin_creator_lines('sandbox') where item->>'payment_id'='annual-2'),'0','renovación anual en mes 13 no genera comisión');
select * from finish(); rollback;
